import { isMacPlatform } from './utils.ts';

export type StringValue = string | ((...args: Array<string | number>) => string);
export type LocaleDictionary = Record<string, StringValue>;
export type StringTables = Record<string, LocaleDictionary>;


// ============================================================
// i18n Framework
// ============================================================

// Russian plural helper (3 forms: one, few, many)
function ruPlural(n: number | string, one: string, few: string, many: string): string {
    const num = Number(n);
    const mod100 = Math.abs(num) % 100;
    const mod10 = mod100 % 10;
    if (mod100 >= 11 && mod100 <= 14) return many;
    if (mod10 === 1) return one;
    if (mod10 >= 2 && mod10 <= 4) return few;
    return many;
}

// Arabic plural helper (singular for 1/11+, dual for 2, plural for 3-10)
function arPlural(n: number | string, one: string, two: string, few: string, many: string): string {
    const num = Number(n);
    if (num === 1) return one;
    if (num === 2) return two;
    if (num <= 10) return String(n) + ' ' + few;
    return String(n) + ' ' + many;
}

// isMacPlatform imported from ./utils.ts

function platformLabel(macText: string, otherText: string): () => string {
    return function () {
        return isMacPlatform() ? macText : otherText;
    };
}

function modifiedClickLabel(baseText: string, macKey: string, otherKey: string): () => string {
    return function () {
        return (isMacPlatform() ? macKey : otherKey) + ' + ' + baseText;
    };
}

