for (const restoreLang of Object.keys(RESTORE_STRINGS)) {
    const strDict = STRINGS[restoreLang];
    if (!strDict) continue;
    const restoreDict = RESTORE_STRINGS[restoreLang]!;
    for (const restoreKey of Object.keys(restoreDict)) {
        strDict[restoreKey] = restoreDict[restoreKey]!;
    }
}

for (const resetLang of Object.keys(RESET_STRINGS)) {
    const strDict = STRINGS[resetLang];
    if (!strDict) continue;
    const resetDict = RESET_STRINGS[resetLang]!;
    for (const resetKey of Object.keys(resetDict)) {
        strDict[resetKey] = resetDict[resetKey]!;
    }
}

