for (const sessionStorageLang of Object.keys(STRINGS)) {
    const strDict = STRINGS[sessionStorageLang]!;
    const sessionStorageStrings = SESSION_STORAGE_STRINGS[sessionStorageLang] || SESSION_STORAGE_STRINGS.en || {};
    for (const sessionStorageKey of Object.keys(sessionStorageStrings)) {
        if (strDict[sessionStorageKey] === undefined) {
            strDict[sessionStorageKey] = sessionStorageStrings[sessionStorageKey]!;
        }
    }
}

