export { STRINGS, ruPlural, arPlural, platformLabel, modifiedClickLabel };

function navigatorLanguage(): string {
    return (typeof navigator !== 'undefined' && navigator.language) || '';
}

export let L: LocaleDictionary = STRINGS.en || {};

export function resolveLocale(override?: string): LocaleDictionary {
    const lang = override && override !== 'auto' ? override : navigatorLanguage();
    let key = lang.slice(0, 2);
    if (key === 'zh') {
        key = /TW|HK|Hant/i.test(lang) ? 'zh-TW' : 'zh';
    }
    const resolved = (STRINGS[key] || STRINGS.en) as LocaleDictionary;
    if (resolved !== STRINGS.en && STRINGS.en) {
        const enKeys = Object.keys(STRINGS.en);
        for (let i = 0; i < enKeys.length; i++) {
            const k = enKeys[i]!;
            if (resolved[k] === undefined) {
                resolved[k] = STRINGS.en[k]!;
            }
        }
    }
    L = resolved;
    return resolved;
}

const defaultExport = {
    get L() {
        return L;
    },
    LANG_OPTIONS,
    LANG_ORDER,
    STRINGS,
    resolveLocale,
    ruPlural,
    arPlural,
    platformLabel,
    modifiedClickLabel,
};

export default defaultExport;
